/* Agent-preset chip on the new-session screen, beside the workspace picker.
   Geometry mirrors HeroShell's .workspace so the two read as one row. */

/* Overflow-driven degradation (mirrors HeroShell's .workspace), no
   breakpoint: the label shrinks with an ellipsis down to nothing, so the
   preset icon and chevron always sit snug against whatever text remains —
   full text, ellipsized text, or none. */
/* The Menu anchor wrapper between the row and this chip: its flex
   auto-minimum would hold the full label width and the row could never
   compress the chip. The explicit floor is the icon-only end state — 8px
   paddings + 16px icon + two 4px gaps + 14px chevron — so the glyphs never
   crush once the label has ellipsized away to nothing. */
.menuAnchor {
  min-width: 54px;
  max-width: 100%;
}

.seat {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  max-width: min(100%, 240px);
  min-height: 28px;
  padding: 0 8px;
  border: none;
  border-radius: var(--dsw-radius-sm);
  background: transparent;
  color: var(--dsw-alias-label-primary);
  font-size: 13px;
  line-height: 20px;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
}

.seat:not(:disabled):hover,
.seat[aria-expanded='true'] {
  background: var(--dsw-alias-interactive-bg-hover);
}

.seat:disabled {
  cursor: default;
  color: var(--dsw-alias-label-quaternary);
}

.seatIcon {
  flex: none;
  color: var(--dsw-alias-label-primary);
}

.seatLabel {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Introduce cue: the icon eases in on an overshoot-free expo curve (duration
   matches INTRO_TEXT_DELAY_MS, so the characters start the moment it lands),
   then the name's characters fade up on a stagger (delays set inline per
   character). All chars occupy their width from the start, so nothing
   reflows mid-run. */
.introIcon {
  animation: seat-icon-in 0.15s cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes seat-icon-in {
  from {
    opacity: 0;
    transform: scale(0.5);
  }

  to {
    opacity: 1;
    transform: scale(1);
  }
}

/* Wraps the staggered characters into one flex item, so the chip's gap
   applies around the name as a whole rather than between characters. */
.introText {
  display: inline-block;
  white-space: pre;
}

.introChar {
  display: inline-block;
  white-space: pre;
  opacity: 0;
  animation: seat-char-in 0.4s ease-out forwards;
}

@keyframes seat-char-in {
  from {
    opacity: 0;
    transform: translateY(4px);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .introIcon,
  .introChar {
    animation: none;
    opacity: 1;
  }
}

.chevron {
  flex: none;
  color: var(--dsw-alias-label-caption);
}

/* Menu rows carry the name over its description: the id alone never said what
   a preset does, which is why the metadata exists. */
.item {
  display: flex;
  flex-direction: column;
  gap: 2px;
  max-width: 280px;
}

.itemName {
  font-size: 13px;
  line-height: 20px;
  color: var(--dsw-alias-label-primary);
}

.itemDesc {
  font-size: 12px;
  line-height: 16px;
  color: var(--dsw-alias-label-caption);
  white-space: normal;
}

headerSource:
/**
 * The session header's agent-preset label.
 *
 * Read-only by construction: a session's composition is fixed once its
 * conversation starts, and a header is only worth reading after that. Offering
 * a control here would promise a switch the host refuses; naming what the
 * session runs is the honest affordance, and the choice itself lives on the
 * new-session screen ({@link AgentPresetSeat}).
 */

import { useEffect } from 'react'
import type { SnapshotStore } from '@deepseek-ai/dsh-client-store'
import type { InjectFace, PropsLocale, PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'
import { IconAgentPresetOutlineRegular } from '@deepseek-ai/dsh-client-ui-primitives'
// Type-only: pulls the ui-conversation SlotMap merge (the header actions).
import type {} from '@deepseek-ai/dsh-client-ui-conversation/client'
import type {} from '@deepseek-ai/dsh-agent-preset-registry/types'
import type { AgentPresetSettingsState } from './settings-store.ts'
import { presetDisplayText } from './locales.ts'
import css from './AgentPresetLabel.module.css'

/** Registration-side business face for the header label. */
export interface AgentPresetLabelInjected {
  hooks: {
    /** Roster snapshot bound by the renderer as useAgentPresets. */
    agentPresets: SnapshotStore<AgentPresetSettingsState>
  }
  /** Read the roster, so the label can show a name rather than an id. */
  load: () => Promise<void>
}

/** Full component props. */
export type AgentPresetLabelProps =
  PropsRuntime<'conversation.session.header.actions'>
  & PropsLocale<'settings.agentPreset'>
  & InjectFace<AgentPresetLabelInjected>

/**
 * Render this session's agent-preset name beside its title.
 * @param props - composed slot props.
 * @returns the label, or null when the session records no preset.
 */
export function AgentPresetLabel({
  sessionId, useSessions, useAgentPresets, load, t,
}: AgentPresetLabelProps) {
  const preset = useSessions((state) => {
    const value = state.byId[sessionId]?.projectionValues?.agentPreset
    return typeof value === 'string' ? value : undefined
  })
  const options = useAgentPresets(state => state.options)

  useEffect(() => {
    // Deployments that compose no presets never label anything, so the roster
    // is only worth a request once a session reports one.
    if (preset !== undefined) void load()
  }, [preset, load])

  if (preset === undefined) return null

  const option = options.find(entry => entry.id === preset)
  const text = option === undefined ? undefined : presetDisplayText(option, t)
  return (
    <span className={css.label} title={text?.description ?? t('headerHint')}>
      <IconAgentPresetOutlineRegular size={14} className={css.icon} />
      {text?.name ?? preset}
    </span>
  )
}

switchSource:
// Switch: two-state toggle. `label` is required and has no default, so a render
// site cannot ship the control without an accessible name.

import clsx from 'clsx'
import css from './Switch.module.css'

/**
 * Render a toggle switch.
 * @param props.checked - the current state; the control is fully controlled.
 * @param props.onChange - called with the state the click asks for.
 * @param props.label - localized accessible name, owned by the render site.
 * @param props.disabled - whether the control refuses input; owners also set it
 * while a write is in flight, not only when a deployment locks the toggle.
 * @param props.title - localized hover text, typically why the toggle is locked.
 * @param props.className - extra class for layout placement.
 * @returns the switch element.
 */
export function Switch({ checked, onChange, label, disabled = false, title, className }: {
  checked: boolean
  onChange: (next: boolean) => void
  label: string
  disabled?: boolean
  title?: string | undefined
  // `| undefined` so a caller can forward an optional class straight through
  // under exactOptionalPropertyTypes (a CSS-module lookup is string|undefined).
  className?: string | undefined
}) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      aria-label={label}
      title={title}
      disabled={disabled}
      className={clsx(css.switch, className)}
      onClick={() => { onChange(!checked) }}
    >
      <span className={css.thumb} />
    </button>
  )
}

switchCss:
/* The on/off appearance keys off aria-checked rather than a parallel class, so
 * the visual state cannot disagree with the state assistive technology reads.
 *
 * The capsule track and circular thumb opt out of the global superellipse. */
.switch {
  box-sizing: border-box;
  position: relative;
  flex: 0 0 auto;
  width: 36px;
  height: 20px;
  padding: 2px;
  border: 0;
  border-radius: 999px;
  corner-shape: round;
  background: var(--dsw-alias-border-l3);
  cursor: pointer;
}

.switch[aria-checked='true'] {
  background: var(--dsw-alias-brand-primary);
}

.switch:disabled {
  cursor: default;
  opacity: 0.5;
}

.switch:focus-visible {
  outline: var(--dsw-focus-ring-width) solid var(--dsw-focus-ring-color, var(--dsw-alias-state-business-primary));
  outline-offset: 2px;
}

.thumb {
  display: block;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  corner-shape: round;
  background: var(--dsw-alias-label-primary-foreground);
  transition: transform 120ms ease;
}

.switch[aria-checked='false'] .thumb {
  background: var(--dsw-alias-switch-thumb);
}

.switch[aria-checked='true'] .thumb {
  transform: translateX(16px);
}
